CREATE TABLE public.app_user_connections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, connector_id text NOT NULL, connection_key_ciphertext text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,connector_id)); GRANT ALL ON public.app_user_connections TO service_role; ALTER TABLE public.app_user_connections ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.github_workspaces (user_id uuid PRIMARY KEY, oauth_nonce text, repo text, branch text); GRANT ALL ON public.github_workspaces TO service_role; ALTER TABLE public.github_workspaces ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.github_fix_previews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, repo text NOT NULL, branch text NOT NULL, path text NOT NULL, original_sha text NOT NULL, before_code text NOT NULL, after_code text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','pushing','pushed','failed')), created_at timestamptz NOT NULL DEFAULT now()); GRANT ALL ON public.github_fix_previews TO service_role; ALTER TABLE public.github_fix_previews ENABLE ROW LEVEL SECURITY;